"""Portal resolver retirement and public-parent/lifetime evidence are finite and mandatory."""
from pathlib import Path
import subprocess
import unittest
ROOT=Path(__file__).resolve().parents[1]
class TabPortalContextTests(unittest.TestCase):
    def test_original_resolver_parent_and_serialized_evidence(self):
        code=r'''
import assert from 'node:assert/strict';import {originalFactoryContract} from './scripts/api-surface.mjs';import {originalCompilerFactoryContext} from './scripts/api-original-factory-contexts.mjs';import {TAB_PORTAL_SYMBOL,tabPortalContract,tabPortalObservationProblems} from './scripts/api-tab-portal-context.mjs';
const originalFactory=originalFactoryContract('/original/src/material/legacy-tabs/tab-body.ts','MatLegacyTabBodyPortal'),symbol={symbol_id:TAB_PORTAL_SYMBOL,family:'legacy-tabs',kind:'primary',name:'MatLegacyTabBodyPortal',shape:{originalFactory,originalFactoryContext:originalCompilerFactoryContext(originalFactory)}};
const contract=tabPortalContract(symbol);assert.equal(contract.original_arity,4);assert.equal(contract.owned_arity,3);assert.equal(contract.removed_index,0);assert.deepEqual(contract.runtime_requests.map(p=>p.ident),['ViewContainerRef','MatLegacyTabBody','DOCUMENT']);let originalRejected=0;
for(const change of [x=>x.family='foreign',x=>x.kind='testing',x=>x.name='Foreign',x=>x.shape.originalFactory.declaration+=' ',x=>x.shape.originalFactoryContext.parameter_factory_key='foreign',x=>x.shape.originalFactoryContext.factory_parameters[0].optional=true,x=>x.shape.originalFactoryContext.factory_parameters[2].unresolved_expression='forwardRef(() => Foreign)',x=>x.shape.originalFactoryContext.factory_parameters.pop(),x=>x.shape.originalFactoryContext.source_sha256='0'.repeat(64)]){const bad=structuredClone(symbol);change(bad);assert.throws(()=>tabPortalContract(bad));originalRejected++;}assert.equal(originalRejected,9);
const parent={actual_parent_component:true,actual_parent_view_initialized:true,actual_content_element_and_portal_queries:true,parent_self_provider_identical:true,child_ancestor_provider_identical:true,child_self_provider_absent:true,actual_constructor_parent_identical:true,borrowed_parent_view_alive_after_child_teardown:true};
const x={symbol_id:TAB_PORTAL_SYMBOL,original_arity:4,owned_arity:3,removed_index:0,removed_ident:'ComponentFactoryResolver',constructor_calls:1,original_inputs_identical:true,public_parent_identity_matched:true,parent_source:{file:'/test/@angular/cdk/fesm2022/portal.mjs',sha256:'1'.repeat(64),parent_text_sha256:'2'.repeat(64)},total_requests:6,retained_requests:3,classified_requests:3,requests:['NgModuleRef','DOCUMENT','ViewContainerRef'].map((ident,index)=>({ident,spec:'@angular/core',identity_matched:true,unresolved:false,optional:index===0,self:false,skipSelf:false,host:false})),independent_public_parent_view_control:true,fixture_sibling_outlet_isolated:true,attach_detach_preserve_reattach:true,attached_events:2,owned_views_destroyed:true,parent_subscriptions_removed:true,borrowed_parent_view_alive:true};
const row={symbol,factory_outcome:'returned',factory_tab_portal_context:x,factory_tab_portal_parent_context:parent};assert.deepEqual(tabPortalObservationProblems(row),[]);let rejected=0;
for(const change of [x=>x.symbol_id='foreign',x=>x.original_arity++,x=>x.owned_arity++,x=>x.removed_index++,x=>x.removed_ident='Foreign',x=>x.constructor_calls++,x=>x.original_inputs_identical=false,x=>x.public_parent_identity_matched=false,x=>x.parent_source.file='foreign',x=>x.parent_source.sha256='',x=>x.parent_source.parent_text_sha256='',x=>x.parent_source.extra='waiver',x=>x.total_requests++,x=>x.retained_requests++,x=>x.classified_requests++,x=>x.requests.pop(),x=>x.requests.reverse(),x=>x.independent_public_parent_view_control=false,x=>x.fixture_sibling_outlet_isolated=false,x=>x.attach_detach_preserve_reattach=false,x=>x.attached_events++,x=>x.owned_views_destroyed=false,x=>x.parent_subscriptions_removed=false,x=>x.borrowed_parent_view_alive=false,x=>x.extra='waiver']){const bad=structuredClone(row);change(bad.factory_tab_portal_context);assert.ok(tabPortalObservationProblems(bad).length);rejected++;}
for(const index of [0,1,2])for(const change of [x=>x.ident='Twin',x=>x.spec='private',x=>x.identity_matched=false,x=>x.unresolved=true,x=>x.optional=!x.optional,x=>x.self=true,x=>x.skipSelf=true,x=>x.host=true,x=>x.extra='waiver']){const bad=structuredClone(row);change(bad.factory_tab_portal_context.requests[index]);assert.ok(tabPortalObservationProblems(bad).length);rejected++;}
for(const key of Object.keys(parent)){const bad=structuredClone(row);bad.factory_tab_portal_parent_context[key]=false;assert.ok(tabPortalObservationProblems(bad).length);rejected++;}
for(const key of ['factory_tab_portal_context','factory_tab_portal_parent_context']){const bad=structuredClone(row);delete bad[key];assert.ok(tabPortalObservationProblems(bad).length);rejected++;}
assert.equal(rejected,62);for(const id of ['foreign','constructor','__proto__'])assert.equal(tabPortalContract({symbol_id:id}),null);
'''
        result=subprocess.run(['node','--input-type=module','-e',code],cwd=ROOT,capture_output=True,text=True,timeout=10)
        self.assertEqual(result.returncode,0,(result.stdout+result.stderr)[-5000:])
